code.java:
public int findDuplicate(int[] nums) {
    Set<Integer> seen = new HashSet<>();
    for (int x : nums) {
        if (!seen.add(x)) {   // add returns false if already present
            return x;
        }
    }
    return -1;                // unreachable given the guarantee
}

